python3 -c "
import zipfile, xml.etree.ElementTree as ET
M='{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'
z=zipfile.ZipFile('budget.xlsx')
root=ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
rows=[]
for row in root.find(M+'sheetData').findall(M+'row'):
    vals={}
    for c in row.findall(M+'c'):
        ref=c.get('r'); t=c.get('t'); v=c.find(M+'v')
        val=v.text if v is not None else ''
        if val!='':
            try: val=float(val)
            except ValueError: pass
        vals[ref[0]]=val
    rows.append(vals)
exp=[r for r in rows if r.get('C') not in (None,'') and isinstance(r.get('C'),float)]
print('Expense lines (A/B/C):')
for r in rows:
    if r.get('C') and isinstance(r.get('C'),float) and r.get('B') and r.get('B') not in ('Total Income','Total Expenses','BALANCE'):
        print(' ', r.get('A'), '|', r.get('B'), '|', r.get('C'))
cats={}
for r in exp:
    cats.setdefault(r.get('A'),0)
    cats[r.get('A')]+=r.get('C')
print()
for k,v in cats.items(): print(f'  {k}: {v:,.0f}')
print('  TOTAL EXPENSES: {:,.0f}'.format(sum(cats.values())))
"

