python3 -c "
import zipfile, re, xml.etree.ElementTree as ET
M='{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'
z=zipfile.ZipFile('budget.xlsx')
root=ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
rows=[]
for row in root.find(M+'sheetData').findall(M+'row'):
    vals={}
    for c in row.findall(M+'c'):
        ref=c.get('r'); t=c.get('t'); v=c.find(M+'v')
        raw=(v.text if v is not None else '') or ''
        if t in ('n',) and raw!='':
            val=float(raw)
        elif t=='s' and raw!='':
            val=raw
        elif t=='inlineStr':
            val=''.join(x.text or '' for x in c.find(M+'is').iter(M+'t'))
        else:
            val=raw if raw!='' else None
        col=re.match(r'[A-Z]+',ref).group(0)
        vals[col]=val
    rows.append(vals)
print('Expense lines:')
for r in rows:
    if isinstance(r.get('C'),float):
        print('  {:>14} | {:<16} | {:>7,.0f}'.format(r.get('A'),r.get('B'),r.get('C')))
cats={}
for r in rows:
    c=r.get('C')
    if isinstance(c,float):
        cats[r.get('A')]=cats.get(r.get('A'),0)+c
print()
for k,v in cats.items(): print('  {:>14}: {:>6,.0f}'.format(k,v))
print('  ' + '-'*22)
print('  TOTAL EXPENSES: {:,.0f}'.format(sum(cats.values())))
inc=sum(r.get('B') for r in rows if isinstance(r.get('B'),float) and r.get('A') in ('Salary','Side Business','Investments','Other'))
print()
print('  Total Income (for reference): {:,.0f}'.format(inc))
print('  Balance (income - expenses): {:,.0f}'.format(inc-sum(cats.values())))
"
